<template><div class="ui-avatar-group" :aria-label="label"><UiAvatar v-for="item in visible" :key="item.name" v-bind="item" :size="size"/><span v-if="remaining" class="ui-avatar-more">+{{ remaining }}</span></div></template>
<script setup lang="ts">import{computed}from'vue';import UiAvatar from'./UiAvatar.vue';const props=withDefaults(defineProps<{items:Array<{name:string;src?:string}>;max?:number;size?:'sm'|'md'|'lg';label?:string}>(),{max:4,size:'md',label:'成员'});const visible=computed(()=>props.items.slice(0,props.max));const remaining=computed(()=>Math.max(0,props.items.length-props.max));</script>
<style scoped>.ui-avatar-group{display:inline-flex;align-items:center;padding-left:6px}.ui-avatar-group>:deep(*){margin-left:-6px;box-shadow:0 0 0 2px var(--ui-surface)}.ui-avatar-more{display:grid;width:32px;height:32px;place-items:center;border-radius:50%;color:var(--ui-text-muted);background:var(--ui-surface-strong);font-size:11px}</style>
